#include <stdio.h>

typedef union { int i; float f; unsigned char bytes[4]; } Data;

int main() {
    Data d;
    d.i = 0x3F800000;
    printf("Int: %d\n", d.i);
    printf("Float: %f\n", d.f);
    printf("Bytes: ");
    for (int j = 0; j < 4; j++) printf("%02x ", d.bytes[j]);
    printf("\n");
    return 0;
}
